scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
   Name = "FPS Control Panel",
   LoadingTitle = "Delta Executor Tools",
   LoadingSubtitle = "by Gemini",
   ConfigurationSaving = {
      Enabled = true,
      FolderName = "FPSConfig",
      FileName = "FPS_Setter"
   }
})

local MainTab = Window:CreateTab("Settings", 4483362458) -- Settings icon

-- 1. Manual Input Box
MainTab:CreateInput({
   Name = "Enter Custom FPS",
   PlaceholderText = "Default is 60",
   RemoveTextAfterFocusLost = false,
   Callback = function(Text)
      local fpsValue = tonumber(Text)
      if fpsValue then
         setfpscap(fpsValue)
         Rayfield:Notify({
            Title = "FPS Updated",
            Content = "FPS limit set to: " .. fpsValue,
            Duration = 3,
            Image = 4483362458,
         })
      end
   end,
})

-- 2. Button for 99,999 (Unlock FPS)
MainTab:CreateButton({
   Name = "Set FPS to 99999 (Uncapped)",
   Callback = function()
      setfpscap(99999)
      Rayfield:Notify({
         Title = "FPS Uncapped",
         Content = "The FPS limit has been removed.",
         Duration = 3,
         Image = 4483362458,
      })
   end,
})

-- 3. Button for 30 (Battery Saver)
MainTab:CreateButton({
   Name = "Set FPS to 30 (Power Save)",
   Callback = function()
      setfpscap(30)
      Rayfield:Notify({
         Title = "FPS Limited",
         Content = "The FPS limit is now 30.",
         Duration = 3,
         Image = 4483362458,
      })
   end,
})
